package com.pollhub.service;
import com.pollhub.dto.RegisterRequest;import com.pollhub.entity.*;import com.pollhub.exception.DuplicateEmailException;import com.pollhub.repository.*;import com.pollhub.security.JwtService;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AuthServiceTest{
 @Mock UserRepository users;@Mock RoleRepository roles;@Mock PasswordEncoder encoder;@Mock AuthenticationManager manager;@Mock UserDetailsService details;@Mock JwtService jwt;@InjectMocks AuthService service;
 RegisterRequest request(){RegisterRequest r=new RegisterRequest();r.setFirstName("Ana");r.setLastName("Anić");r.setEmail("ANA@test.rs");r.setPassword("password");return r;}
 @Test void registersUser(){Role role=new Role();role.setName("ROLE_USER");when(users.existsByEmail("ana@test.rs")).thenReturn(false);when(roles.findByName("ROLE_USER")).thenReturn(Optional.of(role));when(encoder.encode("password")).thenReturn("hash");when(users.saveAndFlush(any())).thenAnswer(i->{User u=i.getArgument(0);u.setId(1L);return u;});var result=service.register(request());assertEquals("ana@test.rs",result.email());verify(users).saveAndFlush(argThat(u->u.isEnabled()&&u.getPassword().equals("hash")));}
 @Test void rejectsDuplicateEmail(){when(users.existsByEmail("ana@test.rs")).thenReturn(true);assertThrows(DuplicateEmailException.class,()->service.register(request()));verify(users,never()).save(any());}
}
